// ══════════════════════ 进阶题型生成器（答案全部由程序计算，保证正确）══════════════════════

/** 通用计算/应用题：传入 [题干, 答案函数, 解析] */
const cal = (kp, d, items) => items.map(([q, fn, e]) => ca(kp, d, q, fn(), e));

/** 一元二次方程（两根为整数） */
function genQuad(kp, d, pairs) {
  return pairs.map(([p, q]) => {
    const b = -(p + q), c = p * q;
    const bs = b === 0 ? "" : b > 0 ? ` + ${b}x` : ` − ${-b}x`;
    const cs = c === 0 ? "" : c > 0 ? ` + ${c}` : ` − ${-c}`;
    const f1 = p >= 0 ? `−${p}` : `+${-p}`;
    const f2 = q >= 0 ? `−${q}` : `+${-q}`;
    return ca(kp, d, `解方程 $x^2${bs}${cs}=0$，较大的根是？`, Math.max(p, q),
      `因式分解得 $(x${f1})(x${f2})=0$，两根为 ${p}、${q}，较大根为 ${Math.max(p, q)}。`);
  });
}

/** 一元一次不等式（a>0）：解集内最小/最大整数 */
function genIneq(kp, d, triples) {
  return triples.map(([a, b, c, op]) => {
    const x = (c - b) / a;
    const ans = op === ">" ? Math.floor(x) + 1 : Math.ceil(x) - 1;
    return ca(kp, d, `解不等式 $${a}x ${b >= 0 ? `+ ${b}` : `− ${-b}`} ${op} ${c}$，满足条件的最小整数是？`, ans,
      `移项得 $${a}x ${op} ${c - b}$，两边同除以 ${a} 得 $x ${op} ${fmt(x)}$。`);
  });
}

/** 一次函数：给定两点求函数值 */
function genLinearFn(kp, d, items) {
  // [k, b, x] → y = kx + b
  return items.map(([k, b, x]) => cal(kp, d, [[`已知一次函数 $y=${k}x${b >= 0 ? `+${b}` : `${b}`}$，当 $x=${x}$ 时 $y=$ ？`, () => k * x + b,
    `代入得 $y=${k}\\times${x}${b >= 0 ? `+${b}` : `${b}`}=${k * x + b}$。`]])).flat();
}

/** 等差数列第 n 项 */
function genAP(kp, d, items) {
  return items.map(([a1, dd, n]) => {
    const an = a1 + (n - 1) * dd;
    return ca(kp, d, `等差数列 $\\{a_n\\}$ 中 $a_1=${a1}$，公差 $d=${dd}$，则 $a_{${n}}=$ ？`, an,
      `$a_{${n}}=a_1+(${n}-1)d=${a1}+${n - 1}\\times(${dd})=${an}$。`);
  });
}

/** 等比数列第 n 项 */
function genGP(kp, d, items) {
  return items.map(([a1, q, n]) => {
    const an = a1 * q ** (n - 1);
    return ca(kp, d, `等比数列 $\\{a_n\\}$ 中 $a_1=${a1}$，公比 $q=${q}$，则 $a_{${n}}=$ ？`, an,
      `$a_{${n}}=a_1q^{${n - 1}}=${a1}\\times${q}^{${n - 1}}=${fmt(an)}$。`);
  });
}

/** 多项式 f(x)=x³+ax²+bx 在 x₀ 处的导数值 */
function genDeriv(kp, d, items) {
  return items.map(([a, b, x0]) => {
    const v = 3 * x0 * x0 + 2 * a * x0 + b;
    return ca(kp, d, `已知 $f(x)=x^3${a >= 0 ? `+${a}` : `${a}`}x^2${b >= 0 ? `+${b}` : `${b}`}x$，则 $f'(${x0})=$ ？`, v,
      `$f'(x)=3x^2${a >= 0 ? `+${2 * a}` : `${2 * a}`}x${b >= 0 ? `+${b}` : `${b}`}$，代入 $x=${x0}$ 得 $${v}$。`);
  });
}

/** 定积分 ∫₀^m x² dx */
function genIntegral(kp, d, ms) {
  return ms.map(m => {
    const v = m ** 3 / 3;
    return ca(kp, d, `计算定积分 $\\int_0^{${m}} x^2\\,dx=$ ？`, fmt(v),
      `$\\int_0^{${m}}x^2\\,dx=\\frac{x^3}{3}\\Big|_0^{${m}}=\\frac{${m ** 3}}{3}=${fmt(v)}$。`);
  });
}

/** 化学：相对分子质量 / 元素质量分数 */
const AR = { H: 1, C: 12, N: 14, O: 16, Na: 23, Mg: 24, Al: 27, Si: 28, P: 31, S: 32, Cl: 35.5, K: 39, Ca: 40, Fe: 56, Cu: 64, Zn: 65, Ba: 137 };
function mrItem(spec, label) {
  const total = Object.entries(spec).reduce((s, [el, n]) => s + AR[el] * n, 0);
  const detail = Object.entries(spec).map(([el, n]) => `${AR[el]}\\times${n}`).join(" + ");
  const name = label ?? Object.entries(spec).map(([el, n]) => el + (n > 1 ? n : "")).join("");
  return [`计算 ${name} 的相对分子质量`, () => total, `相对分子质量 = ${detail} = ${fmt(total)}。`];
}
function massFractionItem(spec, el, label) {
  const total = Object.entries(spec).reduce((s, [e, n]) => s + AR[e] * n, 0);
  const part = AR[el] * spec[el];
  const pct = Math.round((part / total) * 1000) / 10;
  const name = label ?? Object.entries(spec).map(([e, n]) => e + (n > 1 ? n : "")).join("");
  return [`计算 ${name} 中 ${el} 元素的质量分数（%）`, () => pct, `${el} 的质量分数 = $\\frac{${part}}{${total}}\\times100\\%\\approx${pct}\\%$。`];
}

