const H = "history";
writeBook(H, "义务教育教科书 · 中国历史七年级上册", "七年级上册", [
  mathUnit(1, "史前时期与早期国家", [
    { name: "中国境内早期人类", desc: "了解北京人、元谋人等与原始农耕。", d: 2, core: "元谋人是我国境内目前已确认的最早的古人类之一；北京人已会使用火。半坡居民种粟、河姆渡居民种水稻，是我国原始农耕的代表。", formula: "南稻北粟", mistakes: ["把半坡与河姆渡的作物混淆。"], tips: "北方粟、南方稻。" },
    { name: "夏商周与分封制", desc: "了解早期国家与西周制度。", d: 3, core: "约公元前 2070 年禹建立夏朝，是我国历史上第一个王朝。西周实行分封制，公元前 770 年周平王东迁洛邑，进入东周（春秋战国）。", formula: "夏→商→西周→东周", mistakes: ["把分封制的对象说成只封给平民。"], tips: "分封对象为宗亲、功臣等。" },
    { name: "春秋战国与社会变革", desc: "了解争霸兼并、商鞅变法与百家争鸣。", d: 3, core: "春秋时期铁器牛耕出现推动生产力发展；战国时期商鞅变法使秦国富强。百家争鸣中孔子创立儒家、老子创立道家。", formula: "商鞅变法：废井田、开阡陌、奖励耕战", mistakes: ["把孔子主张说成“法治”"], tips: "孔子讲“仁”，法家讲“法治”。" },
  ], [
    ch("中国境内早期人类", 1, "我国境内目前已确认的最早的古人类之一是（　）", ["北京人", "元谋人", "山顶洞人", "半坡人"], "元谋人", "元谋人年代最早。"),
    ch("中国境内早期人类", 2, "半坡居民种植的主要农作物是（　）", ["水稻", "粟", "小麦", "玉米"], "粟", "北方半坡种粟。"),
    ch("夏商周与分封制", 2, "我国历史上第一个王朝是（　）", ["夏朝", "商朝", "西周", "秦朝"], "夏朝", "夏朝是第一个王朝。"),
    tf("夏商周与分封制", 3, "西周分封制的对象包括宗亲和功臣。", "对", "分封对象广泛。"),
    ch("春秋战国与社会变革", 3, "商鞅变法发生在（　）", ["齐国", "秦国", "楚国", "魏国"], "秦国", "商鞅在秦国变法。"),
    tf("春秋战国与社会变革", 2, "孔子是儒家学派创始人。", "对", "孔子创立儒家。"),
  ], [
    tf("春秋战国与社会变革", 3, "春秋战国时期铁制农具和牛耕得到推广。", "对", "生产力发展的重要标志。"),
    ch("夏商周与分封制", 3, "西周实行分封制的目的是（　）", ["稳定统治", "发展农业", "奖励军功", "推行儒学"], "稳定统治", "分封以巩固统治。"),
    ch("春秋战国与社会变革", 2, "主张“无为而治”的学派是（　）", ["儒家", "道家", "法家", "墨家"], "道家", "道家主张无为。"),
    ch("中国境内早期人类", 3, "河姆渡居民居住的房屋主要是（　）", ["半地穴式", "干栏式", "窑洞", "石屋"], "干栏式", "南方潮湿，住干栏式房屋。"),
  ]),
]);

