const G = "geography";
writeBook(G, "义务教育教科书 · 地理七年级上册", "七年级上册", [
  mathUnit(1, "地球和地图", [
    { name: "地球与经纬网", desc: "掌握地球形状、经纬度与半球划分。", d: 3, core: "地球是两极稍扁、赤道略鼓的不规则球体。纬线指示东西方向，经线指示南北方向。赤道是南北半球分界线，20°W 与 160°E 组成东西半球分界线。", formula: "纬度 0°~90°，经度 0°~180°", mistakes: ["把东西半球界线说成 0° 和 180° 经线。"], tips: "东西半球界线为 20°W、160°E。" },
    { name: "地图三要素与等高线地形图", desc: "掌握比例尺、方向、图例与等高线判读。", d: 3, core: "地图三要素是比例尺、方向、图例。等高线密集处坡陡，稀疏处坡缓；等高线向高处凸出为山谷，向低处凸出为山脊。", formula: "比例尺 = 图上距离 / 实地距离", mistakes: ["把山谷山脊判读颠倒。"], tips: "凸高为谷、凸低为脊。" },
  ], [
    ch("地球与经纬网", 1, "纬线指示的方向是（　）", ["东西方向", "南北方向", "东北方向", "垂直方向"], "东西方向", "纬线指示东西。"),
    ch("地球与经纬网", 2, "南北半球的分界线是（　）", ["本初子午线", "赤道", "20°W", "160°E"], "赤道", "赤道划分南北半球。"),
    ch("地图三要素与等高线地形图", 3, "等高线密集的地方坡度（　）", ["陡", "缓", "相同", "无法判断"], "陡", "密集表示坡陡。"),
    tf("地球与经纬网", 2, "经线的长度都相等。", "对", "经线等长。"),
    tf("地图三要素与等高线地形图", 3, "等高线向高处凸出的部位是山谷。", "对", "凸高为谷。"),
    ca("地图三要素与等高线地形图", 3, "比例尺 1:50000 的地图上量得两地距离 3 cm，实地距离是多少千米？", 1.5, "$3\\times50000=150000$ cm $=1.5$ km。"),
  ], [
    ch("地球与经纬网", 3, "下列地点位于东半球的是（　）", ["10°W", "30°W", "170°E", "180°"], "10°W", "20°W 以东为东半球。"),
    ch("地图三要素与等高线地形图", 2, "地图上表示“山峰”的图例符号是（　）", ["▲", "○", "■", "△±"], "▲", "三角形表示山峰。"),
    tf("地图三要素与等高线地形图", 3, "比例尺越大，表示的范围越小、内容越详细。", "对", "比例尺与详略关系。"),
    ch("地球与经纬网", 2, "地球自转的方向是（　）", ["自西向东", "自东向西", "自南向北", "自北向南"], "自西向东", "自转方向自西向东。"),
  ]),
]);

