const E = "english";
writeBook(E, "人教版 · 英语七年级上册", "七年级上册", [
  mathUnit(1, "词法基础", [
    { name: "名词与冠词", desc: "掌握名词单复数与 a/an/the 用法。", d: 2, core: "可数名词有单复数形式，一般加 -s/-es。a/an 表示泛指，an 用于元音音素开头的词前；the 表示特指。", formula: "an + 元音音素开头", mistakes: ["a useful book（u 发 /j/，用 a）。"], tips: "看读音不看字母。" },
    { name: "代词与数词", desc: "掌握人称代词、物主代词与基数序数词。", d: 3, core: "人称代词主格作主语、宾格作宾语；形容词性物主代词后接名词，名词性物主代词单独使用。", formula: "my book = mine", mistakes: ["混用 its 与 it's。"], tips: "it's = it is。" },
  ], [
    ch("名词与冠词", 1, "There is ___ apple on the table.", ["a", "an", "the", "/"], "an", "apple 以元音音素开头。"),
    ch("名词与冠词", 2, "I have three ___.", ["box", "boxs", "boxes", "boxies"], "boxes", "以 x 结尾加 -es。"),
    ch("代词与数词", 2, "This book is ___. (我的)", ["I", "me", "my", "mine"], "mine", "名词性物主代词单独使用。"),
    tf("代词与数词", 3, "“它的”用 its，“它是”用 it's。", "对", "两者区别。"),
  ], [
    ch("名词与冠词", 3, "He is ___ honest boy.", ["a", "an", "the", "/"], "an", "honest 中 h 不发音，以元音音素开头。"),
    ch("代词与数词", 2, "Give ___ the book, please. (我)", ["I", "me", "my", "mine"], "me", "作宾语用宾格。"),
    tf("名词与冠词", 2, "不可数名词没有复数形式。", "对", "如 water。"),
    ch("代词与数词", 3, "There are ___ students in the room.", ["twelve", "twelveth", "the twelve", "twelfth"], "twelve", "基数词表示数量。"),
  ]),
]);

