writeBook(B, "普通高中教科书 · 生物学必修1（高一上册）", "必修1", [
  mathUnit(1, "组成细胞的分子", [
    { name: "蛋白质与核酸", desc: "掌握蛋白质结构多样性与核酸功能。", d: 4, core: "蛋白质基本单位是氨基酸，结构多样性由氨基酸种类、数目、排列顺序和肽链空间结构决定。核酸是遗传信息的携带者，DNA 双链、RNA 单链。", formula: "脱水缩合：肽键数 = 氨基酸数 − 肽链数", mistakes: ["计算肽键时忘记减去肽链数。"], tips: "环状肽另有区别。" },
    { name: "糖类、脂质与水盐", desc: "掌握四大类有机物与无机物的功能。", d: 3, core: "糖类是主要能源物质，脂肪是良好储能物质，蛋白质是生命活动的主要承担者，核酸控制遗传变异。水是含量最多的化合物。", formula: "细胞中含量最多：水", mistakes: ["把蛋白质当含量最多的化合物。"], tips: "最多的是水，最多的有机物是蛋白质。" },
  ], [
    ch("蛋白质与核酸", 2, "蛋白质的基本组成单位是（　）", ["葡萄糖", "氨基酸", "核苷酸", "脂肪酸"], "氨基酸", "氨基酸是蛋白质单体。"),
    ca("蛋白质与核酸", 3, "由 100 个氨基酸构成的含 2 条肽链的蛋白质，肽键数为多少？", 98, "$100-2=98$ 个肽键。"),
    tf("蛋白质与核酸", 3, "DNA 主要分布在细胞核中。", "对", "DNA 主要在细胞核。"),
    ch("糖类、脂质与水盐", 2, "细胞中含量最多的化合物是（　）", ["蛋白质", "水", "糖类", "脂质"], "水", "水含量最多。"),
    ch("糖类、脂质与水盐", 3, "作为储能物质的脂质主要是（　）", ["磷脂", "脂肪", "胆固醇", "维生素 D"], "脂肪", "脂肪是储能物质。"),
  ], [
    ch("蛋白质与核酸", 3, "蛋白质结构多样性的原因不包括（　）", ["氨基酸种类不同", "氨基酸数目不同", "氨基酸排列顺序不同", "氨基酸都含氨基和羧基"], "氨基酸都含氨基和羧基", "这是共性不是多样性原因。"),
    tf("糖类、脂质与水盐", 3, "核酸的基本单位是核苷酸。", "对", "核苷酸是核酸单体。"),
    ca("蛋白质与核酸", 3, "50 个氨基酸形成 1 条肽链，失去水分子多少个？", 49, "失水数 = 肽键数 = 49。"),
    tf("糖类、脂质与水盐", 2, "自由水比例越高，细胞代谢越旺盛。", "对", "自由水与代谢相关。"),
  ]),
  mathUnit(2, "细胞的基本结构与物质运输", [
    { name: "细胞器与细胞核", desc: "掌握主要细胞器功能与细胞核结构。", d: 4, core: "线粒体是有氧呼吸的主要场所，叶绿体是光合作用场所，核糖体是蛋白质合成场所，高尔基体与分泌物的形成有关。细胞核是遗传信息库和代谢控制中心。", formula: "线粒体 = 动力车间", mistakes: ["把核糖体当作蛋白质加工场所。"], tips: "合成在核糖体，加工靠内质网和高尔基体。" },
    { name: "物质跨膜运输", desc: "掌握被动运输、主动运输与胞吞胞吐。", d: 4, core: "自由扩散和协助扩散不消耗能量，主动运输需要载体蛋白并消耗 ATP。大分子进出通过胞吞、胞吐。", formula: "主动运输：逆浓度 + 耗能 + 载体", mistakes: ["把协助扩散当作耗能过程。"], tips: "看是否逆浓度、是否耗能。" },
  ], [
    ch("细胞器与细胞核", 2, "有氧呼吸的主要场所是（　）", ["线粒体", "叶绿体", "核糖体", "液泡"], "线粒体", "线粒体是有氧呼吸主要场所。"),
    ch("物质跨膜运输", 3, "需要载体蛋白且消耗能量的是（　）", ["自由扩散", "协助扩散", "主动运输", "渗透作用"], "主动运输", "主动运输特点。"),
    tf("细胞器与细胞核", 3, "细胞核是遗传信息库，是细胞代谢和遗传的控制中心。", "对", "细胞核功能。"),
    ch("细胞器与细胞核", 3, "与分泌蛋白的加工、运输有关的结构是（　）", ["核糖体、内质网、高尔基体", "线粒体、叶绿体", "溶酶体、液泡", "中心体、核糖体"], "核糖体、内质网、高尔基体", "分泌蛋白途径。"),
    tf("物质跨膜运输", 3, "自由扩散不需要载体蛋白，也不消耗能量。", "对", "自由扩散特点。"),
  ], [
    ch("物质跨膜运输", 3, "将红细胞置于清水中会吸水涨破，说明（　）", ["细胞膜具有选择透过性", "水分子可自由通过细胞膜", "红细胞无细胞壁保护", "细胞内液浓度低于清水"], "红细胞无细胞壁保护", "动物细胞无细胞壁。"),
    tf("细胞器与细胞核", 3, "叶绿体是光合作用的场所，只存在于植物细胞中。", "错", "部分藻类也有，但某些植物细胞（如根细胞）无叶绿体。"),
    ch("细胞器与细胞核", 2, "蛋白质合成的场所是（　）", ["核糖体", "高尔基体", "中心体", "溶酶体"], "核糖体", "核糖体是合成场所。"),
    tf("物质跨膜运输", 3, "胞吞和胞吐体现了细胞膜的流动性。", "对", "依赖膜流动性。"),
  ]),
  mathUnit(3, "细胞的能量供应和利用", [
    { name: "酶与ATP", desc: "掌握酶的特性与 ATP 的作用。", d: 4, core: "酶是活细胞产生的具有催化作用的有机物，具有高效性、专一性，作用条件温和。ATP 是细胞的直接能源物质，远离腺苷的高能磷酸键易断裂释放能量。", formula: "$\\text{ATP}\\rightleftharpoons\\text{ADP}+\\text{Pi}+$ 能量", mistakes: ["把酶都当作蛋白质（少数为 RNA）。"], tips: "绝大多数酶是蛋白质。" },
    { name: "光合作用与细胞呼吸", desc: "掌握两大代谢过程及关系。", d: 4, core: "光合作用把光能转化为化学能储存在有机物中；有氧呼吸把有机物氧化分解并释放能量。光反应需要光，暗反应需要 ATP 与 NADPH。", formula: "$6\\text{CO}_2+12\\text{H}_2\\text{O}\\xrightarrow{\\text{光}}\\text{C}_6\\text{H}_{12}\\text{O}_6+6\\text{O}_2+6\\text{H}_2\\text{O}$", mistakes: ["把暗反应说成只能在夜间进行。"], tips: "暗反应有光也能进行。" },
  ], [
    ch("酶与ATP", 2, "关于酶的叙述正确的是（　）", ["酶都是蛋白质", "酶具有专一性", "酶只能催化一次", "酶在高温下活性更高"], "酶具有专一性", "酶有专一性。"),
    tf("酶与ATP", 2, "ATP 是细胞的直接能源物质。", "对", "ATP 直接供能。"),
    ch("光合作用与细胞呼吸", 3, "光合作用的暗反应阶段不需要（　）", ["ATP", "NADPH", "CO₂", "光"], "光", "暗反应不需要光。"),
    ch("光合作用与细胞呼吸", 3, "有氧呼吸产生 ATP 最多的阶段是（　）", ["第一阶段", "第二阶段", "第三阶段", "都不产生"], "第三阶段", "第三阶段产生最多。"),
    tf("光合作用与细胞呼吸", 3, "光合作用只在光照下进行，呼吸作用在有光无光时都进行。", "对", "呼吸作用不断进行。"),
  ], [
    ch("酶与ATP", 3, "探究酶的最适温度实验中，应（　）", ["直接加酶后测", "先分别保温再混合", "先混合再保温", "在沸水中进行"], "先分别保温再混合", "控制单一变量。"),
    tf("酶与ATP", 3, "酶的作用是降低化学反应的活化能。", "对", "酶的催化机理。"),
    ch("光合作用与细胞呼吸", 3, "把植物置于密闭容器中光照一段时间，CO₂ 浓度下降，说明（　）", ["只进行呼吸作用", "光合作用强度大于呼吸作用强度", "只进行光合作用", "呼吸作用停止"], "光合作用强度大于呼吸作用强度", "净吸收 CO₂。"),
    tf("光合作用与细胞呼吸", 3, "叶绿体中的色素能吸收光能用于光反应。", "对", "色素吸收光能。"),
  ]),
]);

