// ══════════════════════ 追加单元（补充单元较少的教材）══════════════════════
/** 在已生成教材后追加单元：读取现有 outline，续写单元号与题库 */
function extendBook(subject, stem, textbook, unitList) {
  const outPath = path.join(OUTPUT, subject, "outlines", `${stem}.json`);
  const quizDir = path.join(OUTPUT, subject, "quizzes");
  const outline = JSON.parse(fs.readFileSync(outPath, "utf-8"));
  const base = outline.units.length;
  for (const u of unitList) {
    const n = base + u.n;
    outline.units.push({
      unit_number: n, title: u.title,
      knowledge_points: u.kps.map(k => ({ name: k.name, description: k.desc, difficulty: k.d ?? 2, question_types: k.qt ?? ["选择", "填空", "计算"] })),
    });
    reset();
    const unitQuestions = u.qs.map(q => ({ id: ++QID, ...q }));
    const examQuestions = (u.exam ?? []).map(q => ({ id: ++QID, ...q }));
    const quiz = {
      textbook, unit: u.title, unit_number: n,
      unit_test: { title: `第${n}单元「${u.title}」基础过关测验`, total_score: 100, time_minutes: 40, questions: unitQuestions },
      knowledge_summary: u.kps.map(k => ({ point: k.name, core_concept: k.core, key_formula: k.formula ?? "", common_mistakes: k.mistakes ?? [], tips: k.tips ?? "" })),
    };
    if (examQuestions.length >= 4) quiz.exam = { questions: examQuestions };
    fs.writeFileSync(path.join(quizDir, `${stem}_unit${n}.json`), JSON.stringify(quiz, null, 2), "utf-8");
    stats.units++; stats.questions += unitQuestions.length + examQuestions.length;
  }
  fs.writeFileSync(outPath, JSON.stringify(outline, null, 2), "utf-8");
  stats.extended = (stats.extended ?? 0) + 1;
}

// —— 初中生物 七下：补「人体呼吸循环」「人体调节」——
extendBook(B, "义务教育教科书 · 生物学七年级下册", "七年级下册", [
  mathUnit(1, "人体的呼吸与循环", [
    { name: "呼吸系统与血液循环", desc: "掌握呼吸系统组成、血液成分与循环途径。", d: 4, core: "呼吸系统由呼吸道和肺组成，肺泡适于气体交换。血液由血浆和血细胞组成，红细胞含血红蛋白运输氧气。血液循环分体循环与肺循环。", formula: "体循环：左心室→主动脉→…→右心房", mistakes: ["认为动脉里一定流动脉血。"], tips: "肺动脉里流静脉血。" },
    { name: "泌尿系统与排泄", desc: "掌握泌尿系统组成与尿液形成。", d: 3, core: "泌尿系统由肾脏、输尿管、膀胱、尿道组成。尿液形成经肾小球滤过和肾小管重吸收两个过程。", formula: "肾小球滤过 + 肾小管重吸收", mistakes: ["认为原尿中含大量血细胞。"], tips: "正常尿液中无血细胞与葡萄糖。" },
  ], [
    ch("呼吸系统与血液循环", 3, "血液中运输氧气的成分是（　）", ["血浆", "红细胞", "白细胞", "血小板"], "红细胞", "红细胞含血红蛋白。"),
    ch("呼吸系统与血液循环", 4, "体循环的起点是（　）", ["左心室", "右心室", "左心房", "右心房"], "左心室", "体循环起于左心室。"),
    tf("泌尿系统与排泄", 3, "尿液的形成包括肾小球的滤过和肾小管的重吸收。", "对", "尿液形成两过程。"),
    tf("呼吸系统与血液循环", 4, "肺动脉中流的是静脉血。", "对", "肺动脉流静脉血。"),
  ], [
    ch("呼吸系统与血液循环", 5, "人体内进行气体交换的主要场所是（　）", ["气管", "肺泡", "支气管", "鼻腔"], "肺泡", "肺泡是气体交换场所。"),
    tf("泌尿系统与排泄", 4, "原尿中不含血细胞和大分子蛋白质。", "对", "肾小球滤过作用。"),
    tf("呼吸系统与血液循环", 4, "血小板有止血和加速凝血的作用。", "对", "血小板功能。"),
    ch("泌尿系统与排泄", 4, "形成尿液的器官是（　）", ["肾脏", "膀胱", "输尿管", "尿道"], "肾脏", "肾脏形成尿液。"),
  ]),
  mathUnit(2, "人体的调节与健康生活", [
    { name: "神经系统与反射", desc: "掌握神经调节的基本方式。", d: 4, core: "神经系统由脑、脊髓和神经组成。反射是神经调节的基本方式，反射弧包括感受器、传入神经、神经中枢、传出神经和效应器五部分。", formula: "反射弧五部分", mistakes: ["把感受器与效应器颠倒。"], tips: "先感受后效应。" },
    { name: "激素调节与健康生活", desc: "了解激素调节与青春期健康。", d: 3, core: "激素由内分泌腺分泌，直接进入血液运输。胰岛素能调节血糖，分泌不足可致糖尿病。青春期要养成健康的生活方式。", formula: "胰岛素降低血糖", mistakes: ["认为激素由导管输送。"], tips: "内分泌腺无导管。" },
  ], [
    ch("神经系统与反射", 4, "神经调节的基本方式是（　）", ["反射", "应激性", "适应", "代谢"], "反射", "反射是神经调节基本方式。"),
    ch("神经系统与反射", 5, "反射弧的组成不包括（　）", ["感受器", "神经中枢", "效应器", "红细胞"], "红细胞", "红细胞不属反射弧。"),
    tf("激素调节与健康生活", 3, "胰岛素能降低血糖浓度。", "对", "胰岛素调节血糖。"),
    tf("激素调节与健康生活", 3, "内分泌腺没有导管，分泌物直接进入血液。", "对", "内分泌腺特点。"),
  ], [
    ch("神经系统与反射", 5, "神经冲动在反射弧中的传导方向是（　）", ["感受器→传入神经→神经中枢→传出神经→效应器", "效应器→传出神经→神经中枢", "神经中枢→感受器", "传入神经→感受器"], "感受器→传入神经→神经中枢→传出神经→效应器", "信号传导方向。"),
    tf("激素调节与健康生活", 3, "幼年时生长激素分泌不足会患侏儒症。", "对", "生长激素作用。"),
    tf("神经系统与反射", 4, "大脑皮层是调节人体生理活动的最高级中枢。", "对", "大脑皮层功能。"),
    ch("激素调节与健康生活", 4, "糖尿病患者可通过注射胰岛素治疗，是因为胰岛素（　）", ["能降低血糖", "能升高血糖", "能被消化", "无作用"], "能降低血糖", "胰岛素降血糖。"),
  ]),
]);

// —— 初中历史 七上：补「秦汉」「三国两晋南北朝」——
